<?php
 namespace Pterodactyl\Jobs\Dezerx; use Throwable; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Cache; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Queue\Middleware\WithoutOverlapping; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; use Pterodactyl\Services\Dezerx\Minecraft\MrpackInstaller; use Pterodactyl\Services\Dezerx\Minecraft\ModpackBootstrap; use Pterodactyl\Services\Dezerx\Catalogue\ModpackCatalogue; class InstallModpack extends Job implements ShouldQueue { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 5400; public int $tries = 1; public int $maxExceptions = 1; private const STATUS_TTL = 5400; private const DOWNLOAD_MINUTES = 45; private const STOP_SECONDS = 60; private const DELETE_CHUNK = 100; public function __construct( public Server $server, public string $url, public string $filename, public string $kind, public bool $unpack, public bool $wipe = false, public string $minecraft = '', ) { } public function middleware(): array { return [ (new WithoutOverlapping('modpack:' . $this->server->uuid)) ->releaseAfter(30) ->expireAfter($this->timeout + 60), ]; } public static function statusKey(string $server): string { return 'modpack-install:' . $server; } public static function status(string $server): array { return Cache::get(self::statusKey($server)) ?? ['state' => 'idle', 'message' => '']; } public static function mark(string $server, string $state, string $message): void { Cache::put(self::statusKey($server), ['state' => $state, 'message' => $message], self::STATUS_TTL); } public function handle(): void { $files = new ServerFiles($this->server); self::mark($this->key(), 'stopping', 'Stopping the server.'); if (!$this->stopServer($files)) { $this->abort('The server would not stop, so nothing was changed.'); return; } if ($this->wipe && !$this->emptyRoot($files)) { $this->abort('The server files could not be cleared.'); return; } self::mark($this->key(), 'downloading', "Downloading {$this->filename}."); if (!$files->pullFile('/', $this->url, $this->filename)) { Log::warning('Modpack pull refused by node', $this->context()); $this->abort('The node refused that download.'); return; } if (!$this->awaitFile($files)) { Log::warning('Modpack never arrived on node', $this->context()); $this->abort('That pack did not finish downloading.'); return; } try { self::mark($this->key(), 'done', $this->install($files)); } catch (Throwable $exception) { report($exception); ModpackBootstrap::restore($this->server); $this->abort('That pack could not be installed.'); } } public function failed(?Throwable $exception): void { ModpackBootstrap::restore($this->server); $this->abort('Installing that pack took too long and was stopped.'); } private function install(ServerFiles $files): string { return match ($this->kind) { ModpackCatalogue::KIND_MRPACK => $this->mrpack($files), ModpackCatalogue::KIND_SERVER_ZIP => $this->serverPack($files), ModpackCatalogue::KIND_INSTALLER => $this->fromInstaller($files), default => "{$this->filename} is on the server. This pack ships a manifest rather than a server " . 'download, so the egg has to resolve it from here.', }; } private function serverPack(ServerFiles $files): string { if (!$this->unpack) { return "{$this->filename} is on the server, left packed as asked."; } self::mark($this->key(), 'installing', "Unpacking {$this->filename}."); if (!$files->decompress('/', $this->filename)) { Log::warning('Modpack downloaded but could not be unpacked', $this->context()); return "{$this->filename} is on the server, but the node could not unpack it."; } $files->deletePaths('/', [$this->filename]); return $this->fromInstaller($files); } private function fromInstaller(ServerFiles $files): string { $result = app(ModpackBootstrap::class)->handle( $this->server, $files, $this->minecraft, fn (string $message) => self::mark($this->key(), 'installing', $message), ); return $this->outcome($result); } private function mrpack(ServerFiles $files): string { $result = app(MrpackInstaller::class)->handle( $this->server, $files, $this->filename, fn (string $message) => self::mark($this->key(), 'installing', $message), ); if ($result === null) { return "{$this->filename} is on the server, but its manifest could not be read."; } $message = $this->outcome($result); if ($result['missing'] > 0) { $message .= sprintf(' %d of its files did not arrive, so check the mods folder.', $result['missing']); } return $message; } private function outcome(array $result): string { $message = 'The pack is installed.'; if (($result['target'] ?? null) !== null) { $message .= " The server starts from {$result['target']}."; } else { $message .= ' Nothing on it looked like a server to start, so the startup command was left alone.'; } if (($result['image'] ?? null) !== null) { $message .= ' The image was moved to ' . $this->imageLabel((string) $result['image']) . '.'; } return $message . ' It is stopped - start it when you are ready.'; } private function imageLabel(string $image): string { foreach ((array) $this->server->egg->docker_images as $label => $candidate) { if ($candidate === $image) { return (string) $label; } } return $image; } private function stopServer(ServerFiles $files): bool { if ($files->powerState() === 'offline') { return true; } $files->setPower('kill'); $deadline = microtime(true) + self::STOP_SECONDS; do { sleep(3); if ($files->powerState() === 'offline') { return true; } } while (microtime(true) < $deadline); Log::warning('Server would not stop before modpack install', $this->context()); return false; } private function emptyRoot(ServerFiles $files): bool { self::mark($this->key(), 'installing', 'Deleting the old server files.'); $entries = $files->listFiles('/'); if ($entries === null) { return false; } $names = array_values(array_filter(array_map( fn (array $entry) => (string) ($entry['name'] ?? ''), $entries, ))); foreach (array_chunk($names, self::DELETE_CHUNK) as $chunk) { if (!$files->deletePaths('/', $chunk)) { Log::warning('Could not empty server root before install', $this->context()); return false; } } return true; } private function awaitFile(ServerFiles $files): bool { $deadline = microtime(true) + (self::DOWNLOAD_MINUTES * 60); $previous = null; do { sleep(10); $size = $files->entrySize('/', $this->filename); if ($size !== null && $size > 0 && $size === $previous) { return true; } if ($size !== null && $size > 0) { self::mark( $this->key(), 'downloading', sprintf('Downloading %s - %s so far.', $this->filename, $this->readable($size)), ); } $previous = $size; } while (microtime(true) < $deadline); return false; } private function readable(int $bytes): string { return $bytes >= 1_073_741_824 ? sprintf('%.1f GB', $bytes / 1_073_741_824) : sprintf('%d MB', (int) ($bytes / 1_048_576)); } private function abort(string $message): void { self::mark($this->key(), 'failed', $message); } private function key(): string { return $this->server->uuid; } private function context(): array { return ['server' => $this->server->uuid, 'file' => $this->filename]; } } 